UPDATE TB_MESSAGEHISTORY
	SET SEND_RESULT = #{sendResult},
	DID_MACADDRESS = #{didMacAddress},
	DID_PLAYTIME = NOW(),
	ERROR_MESSAGE = #{errorMessage}
WHERE MSG_SEQ = #{msgSeq}
